#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int num_threads = 1;

    // Per-thread partial sums over contiguous chunks from right to left.
    std::vector<long long> chunk_sum;
    std::vector<long long> carry_from_right;

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();

        #pragma omp single
        {
            num_threads = omp_get_num_threads();
            chunk_sum.assign(num_threads, 0LL);
            carry_from_right.assign(num_threads, 0LL);
        }

        const int T = num_threads;

        // Static block partitioning (contiguous).
        const int base = n / T;
        const int rem  = n % T;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len; // exclusive

        long long local = 0;

        // Reverse prefix within each chunk: scan from right to left.
        for (int i = end - 1; i >= start; --i) {
            local += x[i];
            output[i] = static_cast<int>(local);
        }

        // Safe: each thread writes its own index.
        chunk_sum[tid] = local;

        #pragma omp barrier

        // Compute carry for this chunk from all chunks to its right.
        long long carry = 0;
        for (int t = tid + 1; t < T; ++t) {
            carry += chunk_sum[t];
        }
        carry_from_right[tid] = carry;

        #pragma omp barrier

        // Add carry to all elements in this chunk.
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + carry_from_right[tid]);
        }
    }
}
